#!/bin/bash
set -euo pipefail
root=$(cd -- "$(dirname -- "$0")" && pwd)
cd "$root/linux-7.3.5"
out="$root/out"
export KBUILD_BUILD_USER=probe KBUILD_BUILD_HOST=builder KBUILD_BUILD_VERSION=1
export KBUILD_BUILD_TIMESTAMP='Tue Nov 17 12:00:00 UTC 2026'
scripts/config --file "$out/.config" --set-str LOCALVERSION -probe-stable04 --disable LOCALVERSION_AUTO --disable MODVERSIONS --disable MODULE_SIG --disable KERNEL_LZ4 --enable KERNEL_GZIP --disable WERROR --disable DEBUG_INFO --disable DEBUG_INFO_BTF --enable DEBUG_INFO_NONE --disable RUST --set-str SYSTEM_TRUSTED_KEYS '' --set-str SYSTEM_REVOCATION_KEYS '' --set-str INITRAMFS_SOURCE '' --set-str EXTRA_FIRMWARE 'i915/bxt_dmc_ver1_07.bin edid/harman0960p.bin regulatory.db regulatory.db.p7s' --set-str EXTRA_FIRMWARE_DIR "$root/firmware"
for name in X86_MSR DEVMEM MTD SPI_MEM MTD_SPI_NOR SPI_INTEL SPI_INTEL_PCI ACPI EFI EFI_STUB EFI_MIXED EFI_PARTITION PCI DEVTMPFS DEVTMPFS_MOUNT BLK_DEV_INITRD RD_GZIP IGB VLAN_8021Q INTEL_MEI INTEL_MEI_ME MFD_INTEL_LPSS MFD_INTEL_LPSS_PCI PINCTRL_BROXTON I2C_DESIGNWARE_PCI I2C_DESIGNWARE_PLATFORM I2C_CHARDEV GPIO_CDEV TOUCHSCREEN_ATMEL_MXT INPUT_EVDEV SERIAL_8250 SERIAL_8250_CONSOLE SERIAL_8250_DW SERIAL_8250_LPSS SERIAL_8250_PCI DRM DRM_I915 DRM_BOCHS DRM_VIRTIO_GPU DRM_FBDEV_EMULATION DRM_CLIENT_DEFAULT_FBDEV FB FB_DEVICE FRAMEBUFFER_CONSOLE VT VT_CONSOLE FONTS FONT_8x16 FONT_SUN12x22 LOGO LOGO_LINUX_CLUT224 USB_DWC3 USB_DWC3_PCI USB_DWC3_GADGET USB_CONFIGFS USB_CONFIGFS_ACM USB_CONFIGFS_NCM USB_XHCI_HCD USB_XHCI_PCI MMC MMC_BLOCK MMC_SDHCI MMC_SDHCI_PCI MMC_SDHCI_ACPI VIRTIO_PCI VIRTIO_BLK CFG80211 BRCMUTIL BRCMFMAC BRCMFMAC_PCIE BRCMFMAC_PROTO_MSGBUF; do
 scripts/config --file "$out/.config" -e "$name"
done
scripts/config --file "$out/.config" -d DRM_I915_GVT -d DRM_I915_GVT_KVMGT -d DRM_XE -d DRM_CLIENT_DEFAULT_LOG
make O="$out" ARCH=x86_64 CC=gcc olddefconfig
make O="$out" ARCH=x86_64 CC=gcc -j40 bzImage
cp "$out/arch/x86/boot/bzImage" "$root/artifacts/bzImage"
sha256sum "$root/artifacts/bzImage"
